class GamePlatformPage extends StatefulWidget {
  final String territory;
  final List<GamePlatformGroup> groups;
  const GamePlatformPage({super.key, required this.territory, required this.groups});
  @override State<GamePlatformPage> createState() => _GamePlatformPageState();
}

class _GamePlatformPageState extends State<GamePlatformPage> with SingleTickerProviderStateMixin {
  late final AnimationController _clock = AnimationController(vsync: this, duration: const Duration(seconds: 100))..repeat();
  int? _selected;
  List<GamePlatform> get _platforms => widget.groups.expand((g) => g.platforms).toList(growable: false);
  @override void dispose(){_clock.dispose();super.dispose();}
  void _enter(int i){final p=_platforms[i];Navigator.of(context).push(MaterialPageRoute(builder:(_)=>GameListPage(territory:widget.territory,platform:p.name,externalPlatformIds:p.externalPlatformIds,navigationPlatforms:_platforms,navigationIndex:i)));}
  @override Widget build(BuildContext context){
    final size=MediaQuery.sizeOf(context); final compact=size.width<820;
    return Scaffold(backgroundColor:const Color(0xFF01030A),body:AnimatedBuilder(animation:_clock,builder:(context,_)=>(Stack(fit:StackFit.expand,children:[
      CustomPaint(painter:_Space(_clock.value)),
      SafeArea(child:Padding(padding:EdgeInsets.fromLTRB(compact?14:34,compact?12:24,compact?14:34,0),child:Row(children:[InkWell(onTap:()=>Navigator.of(context).pop(),child:const Padding(padding:EdgeInsets.all(8),child:Icon(Icons.arrow_back_ios_new,size:14,color:Color(0x99FFFFFF)))),const SizedBox(width:10),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${widget.territory.toUpperCase()} / PLATFORM WORLDS',style:const TextStyle(fontSize:11,letterSpacing:3.2,color:Colors.white)),const SizedBox(height:5),const Text('GENERATIONAL ARCHIVE / ORBITAL SYSTEM',style:TextStyle(fontSize:6.5,letterSpacing:2.4,color:Color(0x5AFFFFFF)))]),const Spacer(),Text('${_platforms.length.toString().padLeft(2,'0')} WORLDS',style:const TextStyle(fontSize:7,letterSpacing:2,color:Color(0x66FFFFFF)))]))),
      Center(child:LayoutBuilder(builder:(context,b){final d=math.min(b.maxWidth*(compact?.98:.84),b.maxHeight*(compact?.72:.80));return SizedBox.square(dimension:d,child:Stack(clipBehavior:Clip.none,children:[Positioned.fill(child:CustomPaint(painter:_Orbits(_clock.value,_platforms.length))),for(var i=0;i<_platforms.length;i++)_Node(platform:_platforms[i],index:i,total:_platforms.length,selected:_selected==i,diameter:d,phase:_clock.value,onTap:()=>setState(()=>_selected=_selected==i?null:i),onOpen:()=>_enter(i)),const Positioned.fill(child:IgnorePointer(child:Center(child:_Core())))]));})),
      Positioned(top:compact?74:92,right:compact?14:36,child:Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:8),decoration:BoxDecoration(color:const Color(0xB8060A12),border:Border.all(color:const Color(0x2E8EA5B8))),child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[const Text('ATLAS LINK / ONLINE',style:TextStyle(fontSize:6,letterSpacing:1.6,color:Color(0x709BB0BF))),const SizedBox(height:5),Text('WORLDS ${_platforms.length.toString().padLeft(2,'0')}',style:const TextStyle(fontSize:6,letterSpacing:1.4,color:Color(0x8AFFFFFF))),Text('FOCUS ${_selected==null?'--':(_selected!+1).toString().padLeft(2,'0')}',style:const TextStyle(fontSize:6,letterSpacing:1.4,color:Color(0x8AFFFFFF)))]))),
      Positioned(left:compact?12:34,right:compact?12:34,bottom:compact?12:24,child:_selected==null?const Center(child:Text('1× CLICK FOCUS    2× CLICK ENTER PLATFORM',style:TextStyle(fontSize:6.5,letterSpacing:1.8,color:Color(0x55FFFFFF)))):_Panel(platform:_platforms[_selected!],index:_selected!,total:_platforms.length,onClose:()=>setState(()=>_selected=null),onOpen:()=>_enter(_selected!)))
    ]))));
  }
}

class GamePlatformGroup { final String name; final String subtitle; final List<GamePlatform> platforms; const GamePlatformGroup(this.name,this.subtitle,this.platforms); }
class GamePlatform { final String name; final List<int> externalPlatformIds; const GamePlatform(this.name,this.externalPlatformIds); }

class _Node extends StatelessWidget {
  final GamePlatform platform; final int index,total; final bool selected; final double diameter,phase; final VoidCallback onTap,onOpen;
  const _Node({required this.platform,required this.index,required this.total,required this.selected,required this.diameter,required this.phase,required this.onTap,required this.onOpen});
  @override Widget build(BuildContext context){final c=diameter/2;final orbit=diameter*(.19+(index%5)*.065);final a=-math.pi/2+index*math.pi*2/math.max(1,total)+phase*math.pi*.22*(index.isEven?1:-1);final p=Offset(c+math.cos(a)*orbit,c+math.sin(a)*orbit);final double node=(selected?math.max(72,diameter*.112):math.max(52,diameter*.073)).toDouble();return Positioned(left:p.dx-node/2,top:p.dy-node/2,width:node,height:node+26,child:MouseRegion(cursor:SystemMouseCursors.click,child:GestureDetector(onTap:onTap,onDoubleTap:onOpen,child:Column(children:[SizedBox.square(dimension:node,child:CustomPaint(painter:_World(seed:index,selected:selected,phase:phase))),const SizedBox(height:4),Text(platform.name,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(fontSize:selected?8:6.2,letterSpacing:1.5,color:Colors.white.withValues(alpha:selected?.96:.5)))]))));}
}

class _World extends CustomPainter {
  final int seed; final bool selected; final double phase; const _World({required this.seed,required this.selected,required this.phase});
  @override void paint(Canvas canvas,Size size){final c=size.center(Offset.zero);final r=size.width*.36;final sphere=Rect.fromCircle(center:c,radius:r);final bases=[0xFF8B7A6D,0xFF647B87,0xFF8C927E,0xFF7D6F83,0xFF718A86,0xFF9A806B];final base=Color(bases[seed%bases.length]);if(selected)canvas.drawCircle(c,r*1.58,Paint()..shader=RadialGradient(colors:[const Color(0x5E8EA9BC),Colors.transparent]).createShader(Rect.fromCircle(center:c,radius:r*1.58)));final lx=-.42+math.sin(phase*math.pi*2+seed)*.035;canvas.drawCircle(c,r,Paint()..shader=RadialGradient(center:Alignment(lx,-.5),radius:1.05,colors:[base,base.withValues(alpha:.76),const Color(0xFF26313A),const Color(0xFF04060A)]).createShader(sphere));canvas.save();canvas.clipPath(Path()..addOval(sphere));final random=math.Random(700+seed*91);for(var i=0;i<30;i++){final x=c.dx+(random.nextDouble()*2-1)*r*.88;final y=c.dy+(random.nextDouble()*2-1)*r*.88;canvas.drawCircle(Offset(x,y),.7+random.nextDouble()*r*.06,Paint()..color=Colors.white.withValues(alpha:.02+random.nextDouble()*.055));}final contour=Paint()..style=PaintingStyle.stroke..strokeWidth=.5..color=const Color(0x329BAFBA);for(var i=-2;i<=2;i++)canvas.drawOval(Rect.fromCenter(center:c.translate(i*r*.19,0),width:r*(.44+(i+2)*.16),height:r*1.82),contour);canvas.drawOval(sphere,Paint()..shader=const LinearGradient(begin:Alignment.centerLeft,end:Alignment.centerRight,colors:[Colors.transparent,Color(0xE6000207),Color(0xA6000207)]).createShader(sphere));canvas.restore();canvas.drawCircle(c,r,Paint()..style=PaintingStyle.stroke..strokeWidth=selected?1.25:.65..color=const Color(0x6A9AAEBB));if(selected){canvas.drawArc(Rect.fromCircle(center:c,radius:r*1.17),phase*math.pi*2,1.35,false,Paint()..style=PaintingStyle.stroke..strokeWidth=1.1..color=const Color(0x8A9DB5C6));canvas.drawArc(Rect.fromCircle(center:c,radius:r*1.27),-phase*math.pi*2-1,.8,false,Paint()..style=PaintingStyle.stroke..strokeWidth=.6..color=const Color(0x457C92A4));}}
  @override bool shouldRepaint(covariant _World old)=>old.seed!=seed||old.selected!=selected||old.phase!=phase;
}

class _Orbits extends CustomPainter { final double phase; final int count; const _Orbits(this.phase,this.count); @override void paint(Canvas canvas,Size size){final c=size.center(Offset.zero);for(var i=0;i<7;i++){final r=size.shortestSide*(.18+i*.052);canvas.drawOval(Rect.fromCenter(center:c,width:r*2,height:r*1.15),Paint()..style=PaintingStyle.stroke..strokeWidth=i==6?.9:.45..color=const Color(0x1F90A7B7));}canvas.drawArc(Rect.fromCenter(center:c,width:size.width*.84,height:size.height*.48),phase*math.pi*2,.65,false,Paint()..style=PaintingStyle.stroke..strokeWidth=1.1..color=const Color(0x507F9AAC));} @override bool shouldRepaint(covariant _Orbits old)=>old.phase!=phase||old.count!=count; }
class _Core extends StatelessWidget { const _Core(); @override Widget build(BuildContext context)=>Container(width:58,height:58,decoration:const BoxDecoration(shape:BoxShape.circle,gradient:RadialGradient(colors:[Color(0xFFFFFFFF),Color(0xFFD4C4A4),Color(0xFF695A48),Color(0x00000000)],stops:[0,.2,.48,1]),boxShadow:[BoxShadow(color:Color(0x668F7B5D),blurRadius:30,spreadRadius:8)])); }
class _Panel extends StatelessWidget { final GamePlatform platform; final int index,total; final VoidCallback onClose,onOpen; const _Panel({required this.platform,required this.index,required this.total,required this.onClose,required this.onOpen}); @override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.fromLTRB(18,14,12,14),decoration:BoxDecoration(color:const Color(0xF2070B12),border:Border.all(color:const Color(0x527E98A9)),boxShadow:const[BoxShadow(color:Colors.black87,blurRadius:40)]),child:Row(children:[Container(width:3,height:48,color:const Color(0xFF9DB7C7)),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('PLATFORM WORLD / ${index+1}/$total',style:const TextStyle(fontSize:6.5,letterSpacing:1.8,color:Color(0x62FFFFFF))),const SizedBox(height:5),Text(platform.name,style:const TextStyle(fontSize:16,letterSpacing:2.8,color:Colors.white)),const SizedBox(height:4),const Text('GENERATION ARCHIVE • GAME CATALOG • REGION LINKED',style:TextStyle(fontSize:6.2,letterSpacing:1.3,color:Color(0x70FFFFFF)))])),InkWell(onTap:onClose,child:const Padding(padding:EdgeInsets.all(8),child:Text('×',style:TextStyle(fontSize:18,color:Color(0xAAFFFFFF))))),const SizedBox(width:4),FilledButton(onPressed:onOpen,child:const Text('ENTER ARCHIVE'))])); }
class _Space extends CustomPainter { final double phase; const _Space(this.phase); @override void paint(Canvas canvas,Size size){final rect=Offset.zero&size;canvas.drawRect(rect,Paint()..shader=const RadialGradient(center:Alignment(0,-.05),radius:1.15,colors:[Color(0xFF0C1420),Color(0xFF030711),Color(0xFF010207)]).createShader(rect));final random=math.Random(1188);for(var i=0;i<420;i++){final p=Offset(random.nextDouble()*size.width,random.nextDouble()*size.height);final a=.025+.11*((math.sin(phase*math.pi*2*(1+i%3)+i)+1)/2);canvas.drawCircle(p,.25+random.nextDouble()*.7,Paint()..color=Colors.white.withValues(alpha:a));}canvas.drawOval(Rect.fromCenter(center:Offset(size.width*.52,size.height*.5),width:size.width*.9,height:size.height*.65),Paint()..shader=RadialGradient(colors:[const Color(0x255B7891),Colors.transparent]).createShader(rect));canvas.drawRect(rect,Paint()..shader=const RadialGradient(colors:[Colors.transparent,Color(0xC9000000)],stops:[.5,1]).createShader(rect));} @override bool shouldRepaint(covariant _Space old)=>old.phase!=phase; }
